#include "engine.hpp"
#include <iostream>
int main(){
    try{
        std::string command;
        if(!(std::cin>>command))throw std::runtime_error("native command");
        if(command=="ATLAS"){
            size_t n;std::cin>>n;std::vector<entry> fib;
            for(size_t i=0;i<n;++i){std::string s;int length,hop;std::cin>>s>>length>>hop;
                fib.push_back(make_entry(s,length,hop));}
            BaselineLookup table;table.build(fib);std::cout<<table.edges.size()<<'\n';
            for(auto e:table.edges)std::cout<<hexkey(edge_key(e.address))<<' '<<e.next_hop<<'\n';
        }else if(command=="PACK"){
            size_t r,n,a;std::cin>>r>>n>>a;std::vector<Key> starts,addresses;std::vector<int> hops;
            for(size_t i=0;i<r;++i){std::string s;int hop;std::cin>>s>>hop;starts.push_back(key(s));hops.push_back(hop);}
            std::vector<Layout> nodes;
            for(size_t i=0;i<n;++i){Layout node;size_t b;std::cin>>node.lo>>node.span>>node.mode>>node.cached>>b;
                for(size_t j=0;j<b;++j){int c;std::cin>>c;node.children.push_back(c);}nodes.push_back(node);}
            for(size_t i=0;i<a;++i){std::string s;std::cin>>s;addresses.push_back(key(s));}
            auto result=pack_image(starts,hops,nodes,addresses);std::cout<<result.image<<'\n';
            for(auto answer:result.answers){std::cout<<answer.hop<<' '<<answer.run<<' '<<answer.path.size();
                for(auto off:answer.path)std::cout<<' '<<off;std::cout<<'\n';}
        }else if(command=="TRACE"){
            size_t n;std::string image;std::cin>>n>>image;std::vector<Key> addresses;
            for(size_t i=0;i<n;++i){std::string s;std::cin>>s;addresses.push_back(key(s));}
            for(auto answer:trace_image(image,addresses)){
                std::cout<<answer.hop<<' '<<answer.run<<' '<<answer.path.size();
                for(auto off:answer.path)std::cout<<' '<<off;std::cout<<'\n';
            }
        }else throw std::runtime_error("unknown native command");
        if(!std::cin)throw std::runtime_error("truncated native input");
    }catch(const std::exception&e){std::cerr<<e.what()<<'\n';return 1;}
}

