// engine.hpp -- scalar full-width forwarding library (protocol 3).
//
// The legacy 64-bit interval / fixed-fanout baseline was replaced by exact
// 128-bit atlas compilation, FIDX image packing, packed lookup and the
// cache-budgeted layout planner.  Everything is scalar C++17 with no ISA
// extension beyond baseline x86-64.
#pragma once

#include <algorithm>
#include <array>
#include <cstdint>
#include <cstring>
#include <iostream>
#include <map>
#include <queue>
#include <stdexcept>
#include <string>
#include <vector>

using u128 = unsigned __int128;
using u64 = unsigned long long;

// ---------------------------------------------------------------- utilities

inline std::string hex32(u128 x) {
    static const char* d = "0123456789abcdef";
    std::string s(32, '0');
    for (int i = 31; i >= 0; --i) {
        s[i] = d[unsigned(x & 15)];
        x >>= 4;
    }
    return s;
}

inline u128 parse32(const std::string& s) {
    if (s.size() != 32) throw std::runtime_error("key width");
    u128 v = 0;
    for (char c : s) {
        int d;
        if (c >= '0' && c <= '9') d = c - '0';
        else if (c >= 'a' && c <= 'f') d = c - 'a' + 10;
        else if (c >= 'A' && c <= 'F') d = c - 'A' + 10;
        else throw std::runtime_error("key digit");
        v = (v << 4) | unsigned(d);
    }
    return v;
}

inline void put_u16(char* p, unsigned v) {
    p[0] = char(v & 0xff); p[1] = char((v >> 8) & 0xff);
}
inline void put_u32(char* p, u64 v) {
    for (int i = 0; i < 4; ++i) p[i] = char((v >> (8 * i)) & 0xff);
}
inline void put_u64(char* p, u64 v) {
    for (int i = 0; i < 8; ++i) p[i] = char((v >> (8 * i)) & 0xff);
}
inline void put_u128(char* p, u128 v) {
    for (int i = 0; i < 16; ++i) p[i] = char(unsigned((v >> (8 * i)) & 0xff));
}
inline unsigned get_u16(const char* p) {
    return unsigned(unsigned char(p[0])) | (unsigned(unsigned char(p[1])) << 8);
}
inline u64 get_u32(const char* p) {
    u64 v = 0;
    for (int i = 0; i < 4; ++i) v |= u64(unsigned char(p[i])) << (8 * i);
    return v;
}
inline u64 get_u64(const char* p) {
    u64 v = 0;
    for (int i = 0; i < 8; ++i) v |= u64(unsigned char(p[i])) << (8 * i);
    return v;
}
inline u128 get_u128(const char* p) {
    u128 v = 0;
    for (int i = 0; i < 16; ++i) v |= u128(unsigned char(p[i])) << (8 * i);
    return v;
}

inline std::string hex_string(const std::string& raw) {
    static const char* d = "0123456789abcdef";
    std::string s(raw.size() * 2, '0');
    for (size_t i = 0; i < raw.size(); ++i) {
        s[2 * i] = d[(unsigned char(raw[i]) >> 4) & 15];
        s[2 * i + 1] = d[unsigned char(raw[i]) & 15];
    }
    return s;
}

// ------------------------------------------------------------- atlas stage

struct Route {
    u128 start;
    int length;
    int hop;          // -1 is never a route hop; used for null runs
    bool operator<(const Route& o) const {
        if (start != o.start) return start < o.start;
        return length < o.length;
    }
};

// Maximal forwarding runs: unique starts, coalesced equal next hops.
inline void compile_atlas(const std::vector<Route>& fib,
                          std::vector<u128>& starts,
                          std::vector<int>& hops) {
    const size_t n = fib.size();
    std::vector<u128> pts;
    std::vector<std::vector<int>> startAt, endAt;   // bucketed by sorted point
    pts.reserve(2 * n + 1);
    for (size_t i = 0; i < n; ++i) pts.push_back(fib[i].start);
    for (size_t i = 0; i < n; ++i) {
        if (fib[i].length == 0) continue;           // covers the whole domain
        u128 end = fib[i].start + ((u128)1 << (128 - fib[i].length));
        if (end == 0) continue;                     // end == 2^128
