// Breadth-first reorder of a depth-first built tree.
inline std::vector<Node> to_bfs(const std::vector<Node>& dfs) {
    std::vector<int> order;
    std::vector<int> queue;
    queue.push_back(0);
    size_t head = 0;
    while (head < queue.size()) {
        int cur = queue[head++];
        order.push_back(cur);
        for (int c : dfs[cur].children) queue.push_back(c);
    }
    if (order.size() != dfs.size()) throw std::runtime_error("unreachable node");
    std::vector<int> where(dfs.size(), -1);
    for (size_t i = 0; i < order.size(); ++i) where[order[i]] = int(i);
    std::vector<Node> out(dfs.size());
    for (size_t i = 0; i < order.size(); ++i) {
        out[i] = dfs[order[i]];
        for (int& c : out[i].children) c = where[c];
    }
    return out;
}

