    if (image.size() % 2) throw std::runtime_error("image hex");
    std::string bytes(image.size() / 2, '\0');
    for (size_t i = 0; i < bytes.size(); ++i) {
        int hi, lo;
        char c = image[2 * i];
        if (c >= '0' && c <= '9') hi = c - '0';
        else if (c >= 'a' && c <= 'f') hi = c - 'a' + 10;
        else throw std::runtime_error("image hex");
        c = image[2 * i + 1];
        if (c >= '0' && c <= '9') lo = c - '0';
        else if (c >= 'a' && c <= 'f') lo = c - 'a' + 10;
        else throw std::runtime_error("image hex");
        bytes[i] = char((hi << 4) | lo);
