// engine.cpp -- native stages (ATLAS / PACK / TRACE) and the JSON planner.
#include "engine.hpp"
#include <sstream>

// =====================================================================
// Cache-budgeted layout planner.
//
// For one version the layout is an ordered tree over the canonical run
// range.  Its cost is separable per node, so an interval DP over
// [i,j) with a bounded number of children and a resident-page dimension
// is exact.  Versions are coupled only through the shared page budget,
// which is folded with a min-plus convolution.  The lexicographic
// (work, image_pages) objective is carried in a single integer as
// work*PAGE_WEIGHT + pages, with PAGE_WEIGHT above any reachable page
// count, so the primary and secondary objectives are minimised jointly.
// =====================================================================
namespace {

const int MAXC = 12;                    // cache_pages upper bound
const u128 PAGE_WEIGHT = 100000;        // > max pages of one case
const u128 INFV = (u128(1)) << 100;

struct Val {
    u128 c[MAXC + 1];                   // min cost using at most c pages
};

// min over c1+c2<=c of x[c1]+y[c2], then made monotone
inline void vconv(const Val& x, const Val& y, Val& out) {
    for (int c = 0; c <= MAXC; ++c) out.c[c] = x.c[c] + y.c[0];
    for (int c1 = 0; c1 <= MAXC; ++c1) {
        const u128 xc = x.c[c1];
        for (int c2 = 1; c1 + c2 <= MAXC; ++c2) {
            u128 s = xc + y.c[c2];
            if (s < out.c[c1 + c2]) out.c[c1 + c2] = s;
        }
    }
    for (int c = 1; c <= MAXC; ++c)
        if (out.c[c] > out.c[c - 1]) out.c[c] = out.c[c - 1];
}

inline void vfill(Val& v, u128 x) { for (int c = 0; c <= MAXC; ++c) v.c[c] = x; }
inline void vmin(Val& a, const Val& b) {
    for (int c = 0; c <= MAXC; ++c) if (b.c[c] < a.c[c]) a.c[c] = b.c[c];
}

struct VerCtx {
    int R = 0;
    int hit = 1, miss = 1;
    int dec[3] = {0, 0, 0};
    std::vector<u128> starts;
    std::vector<long long> qpref;                 // prefix sums of per-run Q
    std::vector<long long> touch;                 // (R+1)^2 fetch weights T
    std::vector<Val> A;                 // [i,j)
    std::vector<Val> G[10];             // [b][i,j) forest of b subtrees

    inline int id(int i, int j) const { return i * (R + 1) + j; }
    inline long long T(int i, int j) const { return touch[size_t(i) * (R + 1) + j]; }
    inline long long Q(int i, int j) const { return qpref[j] - qpref[i]; }
    inline u128 spread(int i, int j) const { return starts[j - 1] - starts[i]; }

    // combined cost of one node option, uncached / cached
    inline void nodecost(int kind, int b, int span, int mode, int i, int j,
                         u128& cu, u128& cc, int& pages) const {
        int P = node_alloc(kind, b, span, mode) / 64;
        int K = (kind == 0) ? b - 1 : span;
        long long D = (K + LANES[mode] - 1) / LANES[mode] + dec[mode];
        long long Tij = T(i, j), Qij = Q(i, j);
        u128 wu = u128(P) * u64(miss) * u64(Tij) + u128(D) * u64(Qij);
        u128 wc = u128(P) * u64(hit) * u64(Tij) + u128(D) * u64(Qij);
        cu = wu * PAGE_WEIGHT + u64(P);
        cc = wc * PAGE_WEIGHT + u64(P);
        pages = P;
    }

    void build() {
        const int R = this->R;
        A.assign(size_t(R + 1) * (R + 1), Val());
        for (int b = 1; b <= 9; ++b)
            G[b].assign(size_t(R + 1) * (R + 1), Val());
        for (int s = 1; s <= R; ++s) {
            for (int i = 0; i + s <= R; ++i) {
                const int j = i + s;
                u128 sp = spread(i, j);
                bool legal[3] = {true, sp < (u128(1) << 64), sp < (u128(1) << 32)};
                const int bmax = std::min(9, s);
                for (int b = 2; b <= bmax; ++b) {
                    Val best;
                    vfill(best, INFV);
                    for (int k = i + b - 1; k < j; ++k) {
                        Val tmp;
                        vconv(G[b - 1][id(i, k)], A[id(k, j)], tmp);
                        vmin(best, tmp);
                    }
                    G[b][id(i, j)] = best;
                }
                Val acc;
                vfill(acc, INFV);
                if (s <= 8) {
                    for (int m = 0; m < 3; ++m) {
                        if (!legal[m]) continue;
                        u128 cu, cc;
                        int P;
                        nodecost(1, 0, s, m, i, j, cu, cc, P);
                        Val cand;
                        vfill(cand, INFV);
                        for (int c = 0; c <= MAXC; ++c) {
                            if (cu < cand.c[c]) cand.c[c] = cu;
                            if (c >= P && cc < cand.c[c]) cand.c[c] = cc;
                        }
                        vmin(acc, cand);
                    }
                }
                for (int b = 2; b <= bmax; ++b) {
                    const Val& gb = G[b][id(i, j)];
                    for (int m = 0; m < 3; ++m) {
                        if (!legal[m]) continue;
                        u128 cu, cc;
                        int P;
                        nodecost(0, b, s, m, i, j, cu, cc, P);
                        Val cand;
                        vfill(cand, INFV);
                        for (int c = 0; c <= MAXC; ++c) {
                            u128 a = cu + gb.c[c];
                            if (a < cand.c[c]) cand.c[c] = a;
                            if (c >= P) {
                                u128 d = cc + gb.c[c - P];
                                if (d < cand.c[c]) cand.c[c] = d;
                            }
                        }
                        vmin(acc, cand);
                    }
                }
                A[id(i, j)] = acc;
                G[1][id(i, j)] = acc;
            }
        }
    }

    // ---- reconstruction -------------------------------------------
    int buildNode(int i, int j, int c, u128 target, std::vector<Node>& out) {
        const int s = j - i;
        u128 sp = spread(i, j);
        bool legal[3] = {true, sp < (u128(1) << 64), sp < (u128(1) << 32)};
        const int bmax = std::min(9, s);
        const int idx = int(out.size());
        out.push_back(Node());
        Node n;
        n.lo = i;
        n.span = s;
        for (int m = 0; m < 3 && s <= 8; ++m) {
            if (!legal[m]) continue;
            u128 cu, cc;
            int P;
            nodecost(1, 0, s, m, i, j, cu, cc, P);
            if (cu == target) { n.kind = 1; n.mode = m; n.cached = 0; out[idx] = n; return idx; }
            if (P <= c && cc == target) { n.kind = 1; n.mode = m; n.cached = 1; out[idx] = n; return idx; }
        }
        for (int b = 2; b <= bmax; ++b) {
            const Val& gb = G[b][id(i, j)];
            for (int m = 0; m < 3; ++m) {
                if (!legal[m]) continue;
                u128 cu, cc;
                int P;
                nodecost(0, b, s, m, i, j, cu, cc, P);
                std::vector<int> roots;
                if (cu + gb.c[c] == target) {
                    n.kind = 0; n.mode = m; n.cached = 0; n.children.clear();
                    out[idx] = n;
                    buildForest(b, i, j, c, gb.c[c], out, roots);
                    out[idx].children = roots;
                    return idx;
                }
                if (P <= c && cc + gb.c[c - P] == target) {
                    n.kind = 0; n.mode = m; n.cached = 1; n.children.clear();
                    out[idx] = n;
                    buildForest(b, i, j, c - P, gb.c[c - P], out, roots);
                    out[idx].children = roots;
                    return idx;
                }
            }
        }
        throw std::runtime_error("planner reconstruction failed");
    }

    void buildForest(int b, int i, int j, int c, u128 target,
                     std::vector<Node>& out, std::vector<int>& roots) {
        if (b == 1) {
            roots.push_back(buildNode(i, j, c, target, out));
            return;
        }
        for (int k = i + b - 1; k < j; ++k) {
            const Val& x = G[b - 1][id(i, k)];
            const Val& y = A[id(k, j)];
            for (int c1 = 0; c1 <= c; ++c1) {
                int c2 = c - c1;
                if (x.c[c1] + y.c[c2] == target) {
                    buildForest(b - 1, i, k, c1, x.c[c1], out, roots);
                    roots.push_back(buildNode(k, j, c2, y.c[c2], out));
                    return;
                }
            }
        }
        throw std::runtime_error("forest reconstruction failed");
    }
};

}  // namespace

void plan_case(const CaseInput& ci, PlannedCase& out) {
    const int nv = int(ci.versions.size());
    std::vector<VerCtx> ctx(nv);
    for (int v = 0; v < nv; ++v) {
        VerCtx& V = ctx[v];
        V.R = ci.versions[v].R;
        V.starts = ci.versions[v].starts;
        V.hit = ci.hit; V.miss = ci.miss;
        V.dec[0] = ci.dec[0]; V.dec[1] = ci.dec[1]; V.dec[2] = ci.dec[2];
        const int R = V.R;
        V.qpref.assign(R + 1, 0);
        V.touch.assign(size_t(R + 1) * (R + 1), 0);
        std::vector<std::vector<int>> atRun(R);
        std::vector<long long> weight(ci.bursts.size(), 0);
        for (size_t bi = 0; bi < ci.bursts.size(); ++bi) {
            const BurstInput& b = ci.bursts[bi];
            weight[bi] = b.repeat;
            if (b.version != v) continue;
            for (int r : b.runs) V.qpref[r + 1] += b.repeat;
            std::vector<int> uniq(b.runs);
            std::sort(uniq.begin(), uniq.end());
            uniq.erase(std::unique(uniq.begin(), uniq.end()), uniq.end());
            for (int r : uniq) atRun[r].push_back(int(bi));
        }
        for (int r = 0; r < R; ++r) V.qpref[r + 1] += V.qpref[r];
        {
            std::vector<long long> count(R + 1, 0);
            std::vector<int> nxt(int(ci.bursts.size()), R);
            for (size_t bi = 0; bi < ci.bursts.size(); ++bi) {
                const BurstInput& b = ci.bursts[bi];
                if (b.version == v && !b.runs.empty()) count[R] += b.repeat;
            }
            for (int i = R - 1; i >= 0; --i) {
                for (int bi : atRun[i]) {
                    count[size_t(nxt[bi])] -= weight[bi];
                    nxt[bi] = i;
                    count[i] += weight[bi];
                }
                long long acc = 0;
                for (int j = 0; j <= R; ++j) {
                    V.touch[size_t(i) * (R + 1) + j] = acc;
                    acc += count[j];
                }
            }
        }
        V.build();
    }
    // combine versions under the shared budget
    std::vector<Val> root(nv);
    std::vector<Val> before(nv + 1);
    vfill(before[0], 0);
    for (int v = 0; v < nv; ++v) {
        const int R = ctx[v].R;
        u128 extra = u128(1 + (R * 4 + 63) / 64) * PAGE_WEIGHT;   // header + hop pages
        for (int c = 0; c <= MAXC; ++c)
            root[v].c[c] = ctx[v].A[ctx[v].id(0, R)].c[c] + extra;
        vconv(before[v], root[v], before[v + 1]);
    }
    const int C = std::min(ci.cache, MAXC);
    // allocate the budget back onto versions
    std::vector<int> budget(nv, 0);
    int cur = C;
    for (int v = nv - 1; v >= 0; --v) {
        const Val& pre = before[v];
        const Val& nxt = before[v + 1];
        bool ok = false;
        for (int c1 = 0; c1 <= cur && !ok; ++c1) {
            for (int c2 = 0; c1 + c2 <= cur; ++c2) {
                if (pre.c[c1] + root[v].c[c2] == nxt.c[cur]) {
                    budget[v] = c2;
                    cur = c1;
                    ok = true;
                    break;
                }
            }
        }
        if (!ok) throw std::runtime_error("budget reconstruction failed");
    }
    // materialise layouts
    out.nodes.clear();
    out.offsets.clear();
    out.images.clear();
    for (int v = 0; v < nv; ++v) {
        VerCtx& V = ctx[v];
        const int R = V.R;
        u128 extra = u128(1 + (R * 4 + 63) / 64) * PAGE_WEIGHT;
        u128 target = V.A[V.id(0, R)].c[budget[v]];
        std::vector<Node> dfs;
        V.buildNode(0, R, budget[v], target, dfs);
        std::vector<Node> bfs = to_bfs(dfs);
        Image img = build_image(V.starts, ci.versions[v].hops, bfs);
        out.nodes.push_back(bfs);
        out.offsets.push_back(img.offsets);
        out.images.push_back(hex_string(img.bytes));
    }
}

// =====================================================================
// native command dispatch
// =====================================================================

static void run_atlas() {
    size_t n;
    if (!(std::cin >> n)) throw std::runtime_error("atlas size");
    std::vector<Route> fib(n);
    for (size_t i = 0; i < n; ++i) {
        std::string s;
        int length, hop;
        if (!(std::cin >> s >> length >> hop)) throw std::runtime_error("atlas row");
        fib[i] = Route{parse32(s), length, hop};
    }
    std::vector<u128> starts;
    std::vector<int> hops;
    compile_atlas(fib, starts, hops);
    std::ostringstream os;
    os << starts.size() << '\n';
    for (size_t i = 0; i < starts.size(); ++i)
        os << hex32(starts[i]) << ' ' << hops[i] << '\n';
    std::cout << os.str();
}

static void run_pack() {
    size_t r, n, a;
    if (!(std::cin >> r >> n >> a)) throw std::runtime_error("pack size");
    std::vector<u128> starts(r);
    std::vector<int> hops(r);
    for (size_t i = 0; i < r; ++i) {
        std::string s;
        int hop;
        if (!(std::cin >> s >> hop)) throw std::runtime_error("pack run");
        starts[i] = parse32(s);
        hops[i] = hop;
    }
    std::vector<Node> nodes(n);
    for (size_t i = 0; i < n; ++i) {
        Node& nd = nodes[i];
        size_t b;
        if (!(std::cin >> nd.lo >> nd.span >> nd.mode >> nd.cached >> b))
            throw std::runtime_error("pack node");
        nd.kind = b ? 0 : 1;
        nd.children.resize(b);
        for (size_t j = 0; j < b; ++j)
            if (!(std::cin >> nd.children[j])) throw std::runtime_error("pack child");
    }
    std::vector<u128> addrs(a);
    for (size_t i = 0; i < a; ++i) {
        std::string s;
        if (!(std::cin >> s)) throw std::runtime_error("pack address");
        addrs[i] = parse32(s);
    }
    Image img = build_image(starts, hops, nodes);
    std::cout << hex_string(img.bytes) << '\n';
    std::ostringstream os;
    for (size_t i = 0; i < a; ++i) {
        Answer ans;
        lookup_image(img.bytes, addrs[i], ans);
        os << ans.hop << ' ' << ans.run << ' ' << ans.path.size();
        for (int off : ans.path) os << ' ' << off;
        os << '\n';
    }
    std::cout << os.str();
}

static void run_trace() {
    size_t a;
    std::string image;
    if (!(std::cin >> a >> image)) throw std::runtime_error("trace size");
    if (image.size() % 2) throw std::runtime_error("image hex");
    std::string bytes(image.size() / 2, '\0');
    for (size_t i = 0; i < bytes.size(); ++i) {
        int hi, lo;
        char c = image[2 * i];
        if (c >= '0' && c <= '9') hi = c - '0';
        else if (c >= 'a' && c <= 'f') hi = c - 'a' + 10;
        else throw std::runtime_error("image hex");
        c = image[2 * i + 1];
        if (c >= '0' && c <= '9') lo = c - '0';
        else if (c >= 'a' && c <= 'f') lo = c - 'a' + 10;
        else throw std::runtime_error("image hex");
        bytes[i] = char((hi << 4) | lo);
    }
    std::ostringstream os;
    for (size_t i = 0; i < a; ++i) {
        std::string s;
        if (!(std::cin >> s)) throw std::runtime_error("trace address");
        Answer ans;
        lookup_image(bytes, parse32(s), ans);
        os << ans.hop << ' ' << ans.run << ' ' << ans.path.size();
        for (int off : ans.path) os << ' ' << off;
        os << '\n';
    }
    std::cout << os.str();
}

static void run_solve() {
    size_t ncases;
    if (!(std::cin >> ncases)) throw std::runtime_error("solve cases");
    std::vector<CaseInput> cases(ncases);
    for (size_t ci = 0; ci < ncases; ++ci) {
        CaseInput& c = cases[ci];
        if (!(std::cin >> c.cache >> c.hit >> c.miss
              >> c.dec[0] >> c.dec[1] >> c.dec[2]))
            throw std::runtime_error("solve case head");
        size_t nv;
        if (!(std::cin >> nv)) throw std::runtime_error("solve versions");
        c.versions.resize(nv);
        for (size_t v = 0; v < nv; ++v) {
            VersionInput& vi = c.versions[v];
            size_t r;
            if (!(std::cin >> r)) throw std::runtime_error("solve runs");
            if (r == 0) throw std::runtime_error("solve run count");
            vi.R = int(r);
            vi.starts.resize(r);
            vi.hops.resize(r);
            for (size_t k = 0; k < r; ++k) {
                std::string s;
                int hop;
                if (!(std::cin >> s >> hop)) throw std::runtime_error("solve run row");
                vi.starts[k] = parse32(s);
                vi.hops[k] = hop;
            }
        }
        size_t nb;
        if (!(std::cin >> nb)) throw std::runtime_error("solve bursts");
        c.bursts.resize(nb);
        for (size_t b = 0; b < nb; ++b) {
            BurstInput& bi = c.bursts[b];
            size_t na;
            if (!(std::cin >> bi.version >> bi.repeat >> na))
                throw std::runtime_error("solve burst head");
            bi.runs.resize(na);
            for (size_t k = 0; k < na; ++k)
                if (!(std::cin >> bi.runs[k])) throw std::runtime_error("solve burst run");
        }
    }
    std::ostringstream os;
    os << "OK\n";
    for (const CaseInput& c : cases) {
        PlannedCase planned;
        plan_case(c, planned);
        for (size_t v = 0; v < planned.nodes.size(); ++v) {
            os << planned.images[v] << '\n';
            os << planned.nodes[v].size() << '\n';
            for (size_t i = 0; i < planned.nodes[v].size(); ++i) {
                const Node& n = planned.nodes[v][i];
                os << planned.offsets[v][i] << ' ' << n.kind << ' ' << n.mode << ' '
                   << n.cached << ' ' << n.lo << ' ' << n.span << ' '
                   << n.children.size();
                for (int ch : n.children) os << ' ' << ch;
                os << '\n';
            }
        }
    }
    std::cout << os.str();
}

int main() {
    std::ios::sync_with_stdio(false);
    std::cin.tie(nullptr);
    try {
        std::string command;
        if (!(std::cin >> command)) throw std::runtime_error("native command");
        if (command == "ATLAS") run_atlas();
        else if (command == "PACK") run_pack();
        else if (command == "TRACE") run_trace();
        else if (command == "SOLVE") run_solve();
        else throw std::runtime_error("unknown native command");
        if (!std::cin) throw std::runtime_error("truncated native input");
        std::string extra;
        if (std::cin >> extra) throw std::runtime_error("trailing native input");
    } catch (const std::exception& e) {
        std::cerr << e.what() << '\n';
        return 1;
    }
    return 0;
}

