// --------------------------------------------------------- image geometry

const int WIDTH[3] = {16, 8, 4};
const int LANES[3] = {4, 8, 16};

struct Node {
    int kind = 0;      // 0 internal, 1 leaf
    int mode = 0;
    int cached = 0;
    int lo = 0;
    int span = 0;
    std::vector<int> children;   // node row indices, left to right
};

inline int node_used(int kind, int b, int span, int mode) {
    int keys = (kind == 0) ? (b - 1) : span;
    int childbytes = (kind == 0) ? 4 * b : 0;
    return 32 + childbytes + keys * WIDTH[mode];
}
inline int node_alloc(int kind, int b, int span, int mode) {
    int used = node_used(kind, b, span, mode);
    return (used + 63) / 64 * 64;
}

struct Image {
    std::string bytes;
    std::vector<int> offsets;    // per node, in record order
    int hopoff = 0;
    int total = 0;
};

// Layout nodes are supplied in breadth-first order; node 0 is the root.
inline Image build_image(const std::vector<u128>& starts,
                         const std::vector<int>& hops,
                         const std::vector<Node>& nodes) {
    const int R = int(starts.size());
    if (R == 0 || nodes.empty()) throw std::runtime_error("empty image");
    Image img;
    img.offsets.assign(nodes.size(), 0);
    int cur = 64;
    for (size_t i = 0; i < nodes.size(); ++i) {
        const Node& n = nodes[i];
        if (n.lo < 0 || n.span <= 0 || n.lo + n.span > R)
            throw std::runtime_error("node range");
        img.offsets[i] = cur;
        cur += node_alloc(n.kind, int(n.children.size()), n.span, n.mode);
    }
    img.hopoff = cur;
    int hopbytes = (R * 4 + 63) / 64 * 64;
    img.total = img.hopoff + hopbytes;
    img.bytes.assign(size_t(img.total), '\0');
    char* p = &img.bytes[0];
    p[0] = 'F'; p[1] = 'I'; p[2] = 'D'; p[3] = 'X'; p[4] = 2;
    put_u32(p + 8, u64(R));
    put_u32(p + 12, u64(nodes.size()));
    put_u32(p + 16, u64(img.hopoff));
    put_u32(p + 20, u64(img.total));
    for (size_t i = 0; i < nodes.size(); ++i) {
        const Node& n = nodes[i];
        int off = img.offsets[i];
        int b = int(n.children.size());
        char* q = p + off;
        q[0] = char(n.kind);
        q[1] = char(n.mode);
        q[2] = char(n.cached);
        q[3] = 0;
        put_u16(q + 4, unsigned(n.lo));
        put_u16(q + 6, unsigned(n.span));
        put_u16(q + 8, unsigned(n.kind == 0 ? b : n.span));
        put_u16(q + 10, 0);
        put_u32(q + 12, u64(node_alloc(n.kind, b, n.span, n.mode)));
        u128 base = starts[n.lo];
        put_u128(q + 16, base);
        char* payload = q + 32;
        if (n.kind == 0) {
            for (int c = 0; c < b; ++c) {
                if (n.children[c] < 0 || size_t(n.children[c]) >= nodes.size())
                    throw std::runtime_error("child index");
                put_u32(payload + 4 * c, u64(img.offsets[n.children[c]]));
            }
            char* kp = payload + 4 * b;
            for (int c = 1; c < b; ++c) {
                u128 key = starts[nodes[n.children[c]].lo];
                if (n.mode == 0) put_u128(kp, key);
                else if (n.mode == 1) put_u64(kp, u64(key - base));
                else put_u32(kp, u64(key - base));

